import{_ as s,o as i,c as e,a4 as l}from"./chunks/framework.vNSRaLQv.js";const u=JSON.parse('{"title":"HomeSense Studio Plus 接管测试清单 v1","description":"","frontmatter":{"title":"HomeSense Studio Plus 接管测试清单 v1","date":"2026-04-29T00:00:00.000Z"},"headers":[],"relativePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_takeover-test-plan-v1-zh.md","filePath":"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_takeover-test-plan-v1-zh.md"}'),n={name:"posts/3-新项目-Stdio-架构旧文档-2026-04-29至05-22_takeover-test-plan-v1-zh.md"};function p(t,a,o,d,c,h){return i(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="homesense-studio-plus-接管测试清单-v1" tabindex="-1">HomeSense Studio Plus 接管测试清单 v1 <a class="header-anchor" href="#homesense-studio-plus-接管测试清单-v1" aria-label="Permalink to &quot;HomeSense Studio Plus 接管测试清单 v1&quot;">​</a></h1><blockquote><p>文档定位：这是“如何接管这份按文档生成出来的项目”的第一份测试与修复清单。 目标不是全面验收所有能力，而是先验证这份代码是否还能接、从哪里开始测最划算、第一条真实闭环应该怎么跑。</p></blockquote><h2 id="_1-先说结论" tabindex="-1">1. 先说结论 <a class="header-anchor" href="#_1-先说结论" aria-label="Permalink to &quot;1. 先说结论&quot;">​</a></h2><p>这份项目代码可以要，而且建议保留。</p><p>原因不是“它已经做完了”，而是：</p><ul><li>架构骨架已经生成出来了。</li><li>后端可以编译。</li><li>路由、事件、Workflow、CLI Bridge、Skills、Memory 这些大件都已经落了代码。</li><li>它确实是按 <code>新生</code> 文档长出来的，不是完全胡写。</li></ul><p>但它还没有被真正接管，所以不能直接拿它去验证最终产品能力。</p><p>正确方式应该是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>保留骨架</span></span>
<span class="line"><span>-&gt; 修关键接缝</span></span>
<span class="line"><span>-&gt; 从一条英雄路径开始测试</span></span>
<span class="line"><span>-&gt; 边测边接管</span></span></code></pre></div><h2 id="_2-第一条英雄路径" tabindex="-1">2. 第一条英雄路径 <a class="header-anchor" href="#_2-第一条英雄路径" aria-label="Permalink to &quot;2. 第一条英雄路径&quot;">​</a></h2><p>第一条必须固定，不要来回变。</p><p>当前 Hero 场景定为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>我想看 B 站</span></span>
<span class="line"><span>-&gt; 意图识别</span></span>
<span class="line"><span>-&gt; 上下文补全为“在东芝电视上看 B 站”</span></span>
<span class="line"><span>-&gt; 调用设备与技能知识</span></span>
<span class="line"><span>-&gt; 通过米家/红外控制电视与机顶盒上电</span></span>
<span class="line"><span>-&gt; 不断等待并连接 ADB</span></span>
<span class="line"><span>-&gt; 查看包名列表</span></span>
<span class="line"><span>-&gt; 启动小电视应用</span></span>
<span class="line"><span>-&gt; 进入可继续操作的 B 站电视端状态</span></span></code></pre></div><p>这条链不是凭空想的，它在老项目里已经有闭环痕迹：</p><ul><li>老项目成功路径里有 <code>watch_bilibili_demo</code>。</li><li>旧链路明确是 <code>hami -&gt; adb wait -&gt; hami -&gt; adb ensure_connected -&gt; adb list_packages(keyword=bili) -&gt; adb launch_app(com.xiaodianshi.tv.yst)</code>；这只作为历史证据保留，V1 当前主线已切换为 <code>mi-cli -&gt; adb-cli</code>。</li></ul><p>对应参考：</p><ul><li><code>D:/files/HomeSense/agent/dist/tools/success_paths/data/paths.json</code></li><li><code>D:/files/HomeSense/新生/00-老项目评估/00-HomeSense老项目正式总档案.md</code></li></ul><p>所以这条路最适合做新项目接管起点，因为它同时证明：</p><ul><li>家庭娱乐场景真实存在。</li><li>老项目确实做过，不是空想。</li><li>新项目只要接住这条线，就能迅速判断骨架值不值得继续投。</li></ul><h2 id="_3-测试目标" tabindex="-1">3. 测试目标 <a class="header-anchor" href="#_3-测试目标" aria-label="Permalink to &quot;3. 测试目标&quot;">​</a></h2><p>这次接管测试不是问“系统高级不高级”，而是问四件事：</p><ol><li>这份代码能不能稳定构建与启动。</li><li>设备执行边界能不能真正跑通。</li><li>Hero 场景能不能形成一条端到端闭环。</li><li>这条闭环能不能成为后续 Chat、Workflow、Studio 的母路径。</li></ol><h2 id="_4-接管原则" tabindex="-1">4. 接管原则 <a class="header-anchor" href="#_4-接管原则" aria-label="Permalink to &quot;4. 接管原则&quot;">​</a></h2><h3 id="先测单一路径-不测整个平台" tabindex="-1">先测单一路径，不测整个平台 <a class="header-anchor" href="#先测单一路径-不测整个平台" aria-label="Permalink to &quot;先测单一路径，不测整个平台&quot;">​</a></h3><p>不要一上来测：</p><ul><li>Studio 全部节点</li><li>多 Agent 调度</li><li>全部设备发现</li><li>全部模型能力</li><li>全部记忆机制</li></ul><p>先只测一条：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>看 B 站</span></span></code></pre></div><h3 id="先测边界-再测智能" tabindex="-1">先测边界，再测智能 <a class="header-anchor" href="#先测边界-再测智能" aria-label="Permalink to &quot;先测边界，再测智能&quot;">​</a></h3><p>测试顺序必须是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>构建</span></span>
<span class="line"><span>-&gt; CLI 契约</span></span>
<span class="line"><span>-&gt; 执行链路</span></span>
<span class="line"><span>-&gt; Chat</span></span>
<span class="line"><span>-&gt; Experience 写回</span></span>
<span class="line"><span>-&gt; Workflow/Studio</span></span></code></pre></div><p>不是反过来。</p><h3 id="先用老项目经验对齐新项目-不急着推倒重写" tabindex="-1">先用老项目经验对齐新项目，不急着推倒重写 <a class="header-anchor" href="#先用老项目经验对齐新项目-不急着推倒重写" aria-label="Permalink to &quot;先用老项目经验对齐新项目，不急着推倒重写&quot;">​</a></h3><p>旧项目已经证明过“这条路能走通”，新项目的任务不是重新发明，而是：</p><ul><li>把旧闭环拆成新架构里的模块。</li><li>找出现在生成代码哪些接缝没接上。</li><li>用第一条母路径验证模块边界是否靠谱。</li></ul><h2 id="_5-第一阶段测试顺序" tabindex="-1">5. 第一阶段测试顺序 <a class="header-anchor" href="#_5-第一阶段测试顺序" aria-label="Permalink to &quot;5. 第一阶段测试顺序&quot;">​</a></h2><h3 id="t0-构建与启动体检" tabindex="-1">T0：构建与启动体检 <a class="header-anchor" href="#t0-构建与启动体检" aria-label="Permalink to &quot;T0：构建与启动体检&quot;">​</a></h3><p>目标：</p><ul><li>确认当前工程不是死骨架。</li></ul><p>必须检查：</p><ul><li>backend 是否能 build。</li><li>frontend 是否能 build。</li><li>backend 是否能启动。</li><li>DB 是否能初始化。</li><li>skills 是否能加载。</li></ul><p>当前已知结论：</p><ul><li>backend 可以编译通过。</li><li>frontend 当前构建失败，原因是 <code>@vue-flow/background/dist/style.css</code> 导入路径不对。</li><li>skills parser 与现有 <code>SKILL.md</code> 表格格式不一致。</li></ul><p>这一阶段通过标准：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>npm run build</span></span>
<span class="line"><span>npm run dev:backend</span></span>
<span class="line"><span>npm run dev:frontend</span></span></code></pre></div><p>至少要修到：</p><ul><li>前后端都能起。</li><li>启动后没有立刻因为 schema 或依赖问题崩掉。</li></ul><h3 id="t1-cli-契约测试" tabindex="-1">T1：CLI 契约测试 <a class="header-anchor" href="#t1-cli-契约测试" aria-label="Permalink to &quot;T1：CLI 契约测试&quot;">​</a></h3><p>目标：</p><ul><li>验证 <code>backend -&gt; cliBridge -&gt; mi-cli</code> 这条边界。</li></ul><p>必须检查：</p><ul><li>action 名称是否一致。</li><li>params 结构是否一致。</li><li>成功结构和错误结构是否稳定。</li><li>stdout 是否干净 JSON。</li><li>timeout 是否可控。</li></ul><p>这一阶段不是测智能，而是测“手还在不在”。</p><p>通过标准：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>TS 可以稳定调用 Python CLI</span></span>
<span class="line"><span>CLI 返回结构固定</span></span>
<span class="line"><span>错误不会把上层打穿</span></span></code></pre></div><h3 id="t2-hero-场景拆段测试" tabindex="-1">T2：Hero 场景拆段测试 <a class="header-anchor" href="#t2-hero-场景拆段测试" aria-label="Permalink to &quot;T2：Hero 场景拆段测试&quot;">​</a></h3><p>不要一上来整条自动跑完。先拆成 5 段：</p><ol><li><p><code>意图与上下文</code></p><ul><li>输入：<code>我想看 B 站</code></li><li>输出：识别成“在东芝电视上看 B 站”</li></ul></li><li><p><code>设备执行计划</code></p><ul><li>输出步骤应接近：</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>开东芝电视</span></span>
<span class="line"><span>开机顶盒</span></span>
<span class="line"><span>等待 ADB 在线</span></span>
<span class="line"><span>查包名</span></span>
<span class="line"><span>打开 B 站电视应用</span></span></code></pre></div></li><li><p><code>红外执行</code></p><ul><li>能否通过米家/红外中枢控制电视和机顶盒上电。</li></ul></li><li><p><code>ADB 接管</code></p><ul><li>能否不断尝试连接。</li><li>能否拉包名列表。</li><li>能否启动 <code>com.xiaodianshi.tv.yst</code>。</li></ul></li><li><p><code>状态确认</code></p><ul><li>至少能知道：设备已进入“B 站电视端可继续操作状态”。</li></ul></li></ol><p>这 5 段都通了，整条 Hero 路径才算通。</p><h3 id="t3-chat-闭环测试" tabindex="-1">T3：Chat 闭环测试 <a class="header-anchor" href="#t3-chat-闭环测试" aria-label="Permalink to &quot;T3：Chat 闭环测试&quot;">​</a></h3><p>目标：</p><ul><li>让 Hero 场景通过 Chat 跑起来。</li></ul><p>最小通过标准：</p><ul><li>Chat 输入：<code>我想看 B 站</code></li><li>Agent 能产出步骤</li><li>能触发真实执行链</li><li>Trace 有过程</li><li>最终有成功/失败结果</li></ul><p>这一阶段还不要求：</p><ul><li>很强的多轮对话</li><li>很漂亮的 UI</li><li>很复杂的经验检索</li></ul><h3 id="t4-experience-写回测试" tabindex="-1">T4：Experience 写回测试 <a class="header-anchor" href="#t4-experience-写回测试" aria-label="Permalink to &quot;T4：Experience 写回测试&quot;">​</a></h3><p>目标：</p><ul><li>Hero 路径成功后，系统要留下可复用痕迹。</li></ul><p>至少要验证：</p><ul><li>成功后写入 Experience。</li><li>Experience 可被再次召回。</li><li>第二次再说 <code>看 B 站</code> 时，路径更短或更稳定。</li></ul><p>这一步决定新项目是不是只是“新壳子”，还是开始重新拥有老项目的“自增强味道”。</p><h3 id="t5-workflow-接管测试" tabindex="-1">T5：Workflow 接管测试 <a class="header-anchor" href="#t5-workflow-接管测试" aria-label="Permalink to &quot;T5：Workflow 接管测试&quot;">​</a></h3><p>目标：</p><ul><li>把 Hero 路径变成 Workflow，而不是仅停留在 Chat。</li></ul><p>最小要求：</p><ul><li>能把“看 B 站”保存成 Workflow。</li><li>Workflow 可以手动运行。</li><li>Workflow Trace 可见。</li><li>Chat 第二次可以直接调用该 Workflow。</li></ul><p>这一阶段先不要碰多 Agent 中枢，只验证：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>Chat 成功路径</span></span>
<span class="line"><span>-&gt; Experience</span></span>
<span class="line"><span>-&gt; Workflow candidate</span></span>
<span class="line"><span>-&gt; Workflow run</span></span></code></pre></div><h3 id="t6-studio-接管测试" tabindex="-1">T6：Studio 接管测试 <a class="header-anchor" href="#t6-studio-接管测试" aria-label="Permalink to &quot;T6：Studio 接管测试&quot;">​</a></h3><p>目标：</p><ul><li>确认 Studio 不是摆设。</li></ul><p>最小要求：</p><ul><li>画布能显示节点。</li><li>节点保存有效。</li><li>节点运行顺序正确。</li><li>Trace 能反映节点级状态。</li></ul><p>先不追求：</p><ul><li>所有节点类型</li><li>多 Agent 节点</li><li>高级调试面板</li></ul><p>只要能把 <code>看 B 站</code> 这条路径画出来、跑起来，就够了。</p><h2 id="_6-hero-场景标准执行链" tabindex="-1">6. Hero 场景标准执行链 <a class="header-anchor" href="#_6-hero-场景标准执行链" aria-label="Permalink to &quot;6. Hero 场景标准执行链&quot;">​</a></h2><p>接管测试时，默认以这条“目标执行链”作为参照：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>用户：我想看 B 站</span></span>
<span class="line"><span>-&gt; intent_router 判断娱乐/观影意图</span></span>
<span class="line"><span>-&gt; context_completer 结合家庭设备上下文</span></span>
<span class="line"><span>-&gt; 归一化为：在东芝电视上看 B 站</span></span>
<span class="line"><span>-&gt; skills / memory / success path 召回</span></span>
<span class="line"><span>-&gt; 计划：</span></span>
<span class="line"><span>   1. 红外打开东芝电视</span></span>
<span class="line"><span>   2. 红外打开机顶盒</span></span>
<span class="line"><span>   3. ADB 等待电视端上线</span></span>
<span class="line"><span>   4. ADB 查找 bili 相关包名</span></span>
<span class="line"><span>   5. ADB 启动 com.xiaodianshi.tv.yst</span></span>
<span class="line"><span>-&gt; Trace 输出全过程</span></span>
<span class="line"><span>-&gt; 写回 Experience</span></span></code></pre></div><p>老项目里的闭环证据是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>mi-cli scene_execute(东芝电视开机)</span></span>
<span class="line"><span>-&gt; mi-cli speaker_execute(打开东芝电视和机顶盒)</span></span>
<span class="line"><span>-&gt; adb wait 15s</span></span>
<span class="line"><span>-&gt; adb ensure_connected(max_attempts=5)</span></span>
<span class="line"><span>-&gt; adb list_packages(keyword=bili)</span></span>
<span class="line"><span>-&gt; adb launch_app(package=com.xiaodianshi.tv.yst)</span></span></code></pre></div><p>新项目测试时，不要求步骤完全一样，但最终闭环要等价。</p><h2 id="_7-第一批必须修的地方" tabindex="-1">7. 第一批必须修的地方 <a class="header-anchor" href="#_7-第一批必须修的地方" aria-label="Permalink to &quot;7. 第一批必须修的地方&quot;">​</a></h2><p>在正式跑 Hero 场景前，我建议只修这些，不多修：</p><ol><li><p>前端构建错误<br><code>StudioView.vue</code> 的 Vue Flow background CSS 导入路径。</p></li><li><p>Skill parser 对齐<br> 让 <code>skills/mi-cli/SKILL.md</code> 的表格 action 能被 backend 正确索引。</p></li><li><p>CLI 协议统一<br> 确认 <code>cliBridge.run()</code> 发送结构与 Python CLI 接收结构一致。</p></li><li><p>启动配置统一<br> DB、skills 目录、provider 配置、CLI 路径在 dev 环境可稳定工作。</p></li><li><p>Trace 最小可见<br> 至少能看到 Hero 场景每一步有没有执行。</p></li></ol><p>这些修复都属于“接管式修复”，不是大重构。</p><h2 id="_8-现有项目还能不能要" tabindex="-1">8. 现有项目还能不能要 <a class="header-anchor" href="#_8-现有项目还能不能要" aria-label="Permalink to &quot;8. 现有项目还能不能要&quot;">​</a></h2><p>答案是：能要，而且现在最不该做的就是推倒重来。</p><p>这份生成项目目前的真实状态更像：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>高级架构骨架已生成</span></span>
<span class="line"><span>+ 一部分代码能工作</span></span>
<span class="line"><span>+ 一部分代码只停留在“形状正确”</span></span>
<span class="line"><span>+ 文档与实现还没完全对齐</span></span></code></pre></div><p>它的问题主要是：</p><ul><li>接缝没接上。</li><li>生成质量不均匀。</li><li>测试还没接管。</li></ul><p>它的价值主要是：</p><ul><li>模块边界已经铺出来。</li><li>新架构方向已经体现在代码里。</li><li>不用从零把 20 多个参考项目重新吸收一遍。</li></ul><p>所以策略应该是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>保留</span></span>
<span class="line"><span>-&gt; 修接缝</span></span>
<span class="line"><span>-&gt; 用 Hero 场景接管</span></span>
<span class="line"><span>-&gt; 再决定哪些模块需要重写</span></span></code></pre></div><h2 id="_9-第一周接管目标" tabindex="-1">9. 第一周接管目标 <a class="header-anchor" href="#_9-第一周接管目标" aria-label="Permalink to &quot;9. 第一周接管目标&quot;">​</a></h2><p>如果按一周节奏来收敛，我建议只追这三个结果：</p><ol><li>前后端都能启动。</li><li><code>我想看 B 站</code> 这条 Hero 路径至少能拆段跑通。</li><li>Hero 路径成功后，能保存为 Workflow 雏形。</li></ol><p>只要这三件事成了，这份项目就被真正接管了。</p><h2 id="_10-接管完成的标志" tabindex="-1">10. 接管完成的标志 <a class="header-anchor" href="#_10-接管完成的标志" aria-label="Permalink to &quot;10. 接管完成的标志&quot;">​</a></h2><p>这份项目什么时候算“从前任 AI 交接到我手里了”？</p><p>不是文档写完的时候。</p><p>而是下面这些都成立的时候：</p><ul><li>我们知道第一条母路径是什么。</li><li>我们知道它在旧项目里确实做过。</li><li>我们知道新项目里哪些模块支撑这条路径。</li><li>我们修完最关键的接缝。</li><li>我们能在新项目里把它重新跑通。</li></ul><p>一旦 <code>看 B 站</code> 这条路在新项目里重新站起来，后面的 Studio、Agent 中枢、B 站 CLI、多 Agent 调度才值得继续扩。</p>`,117)])])}const k=s(n,[["render",p]]);export{u as __pageData,k as default};
